1	package mevwatch
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"sort"
10		"strconv"
11		"strings"
12		"syscall"
13	)
14	
15	// Offline alerting turns conclusions already stored in an archive into
16	// alert processing records. It never re-runs detection: a record always
17	// reflects the finding, the rule version and the parameters that were in
18	// force when the block was archived.
19	
20	// Alert statuses. A finding above the generation threshold becomes an
21	// "alert"; a finding that matches one or more registered suppression
22	// conditions at its block height becomes "suppressed" instead.
23	const (
24		AlertStatusAlert      = "alert"
25		AlertStatusSuppressed = "suppressed"
26	)
27	
28	// Suppression condition kinds.
29	const (
30		SuppressSandwich     = "sandwich"
31		SuppressDisplacement = "displacement"
32	)
33	
34	// ErrUnknownKind reports a conclusion/condition kind that is neither
35	// sandwich nor displacement.
36	var ErrUnknownKind = errors.New("unknown kind")
37	
38	// ErrSuppressionConflict reports re-registering an existing suppression ID
39	// with different content.
40	var ErrSuppressionConflict = errors.New("suppression already registered with different content")
41	
42	// SuppressionHit records one suppression condition that matched an event.
43	type SuppressionHit struct {
44		ID     string `json:"id"`
45		Reason string `json:"reason"`
46	}
47	
48	// ProcessingRecord is one fully resolved alerting outcome. Its identity is
49	// (chain, block hash, victim tx hash, conclusion kind, channel): once a
50	// record exists for that identity, no later import, wider or overlapping
51	// height range, rule-version switch or restart can produce it again. The
52	// record keeps the complete block identity, pool, conclusion, raw swap
53	// evidence, the detection version and its parameters, the threshold used at
54	// generation time, and every suppression condition that matched.
55	type ProcessingRecord struct {
56		ChainID      string           `json:"chainId"`
57		BlockHash    string           `json:"blockHash"`
58		BlockNumber  uint64           `json:"blockNumber"`
59		Pool         string           `json:"pool"`
60		Channel      string           `json:"channel"`
61		Finding      ReportFinding    `json:"finding"`
62		Version      RuleVersion      `json:"version"`
63		MinSeverity  int              `json:"minSeverity"`
64		Status       string           `json:"status"`
65		Suppressions []SuppressionHit `json:"suppressions"`
66	}
67	
68	func (r ProcessingRecord) identity() alertKey {
69		return alertKey{
70			chainID:   r.ChainID,
71			blockHash: r.BlockHash,
72			txHash:    r.Finding.TxHash,
73			kind:      r.Finding.Kind,
74			channel:   r.Channel,
75		}
76	}
77	
78	// Suppression is one registered suppression condition. Every field matches
79	// exactly (the pool is matched against the pool of the victim swap's
80	// original exchange record), and an event at height h is covered when
81	// StartHeight <= h <= EndHeight.
82	type Suppression struct {
83		ID          string `json:"id"`
84		ChainID     string `json:"chainId"`
85		Pool        string `json:"pool"`
86		Kind        string `json:"kind"`
87		Channel     string `json:"channel"`
88		StartHeight uint64 `json:"startHeight"`
89		EndHeight   uint64 `json:"endHeight"`
90		Reason      string `json:"reason"`
91	}
92	
93	// covers reports whether the suppression applies to an event on chain at
94	// height in the given pool/kind/channel. Matching depends only on the
95	// event's height, never on operation time, import order or the archive's
96	// highest block.
97	func (s Suppression) covers(chainID, pool, kind, channel string, height uint64) bool {
98		return s.ChainID == chainID && s.Pool == pool && s.Kind == kind && s.Channel == channel &&
99			s.StartHeight <= height && height <= s.EndHeight
100	}
101	
102	// alertKey is the deduplication identity of a processing record.
103	type alertKey struct {
104		chainID   string
105		blockHash string
106		txHash    string
107		kind      string
108		channel   string
109	}
110	
111	// suppressionSpec mirrors one suppression registration document. Pointers
112	// distinguish missing fields from explicit zero values; heights are parsed
113	// separately as unsigned 64-bit integers.
114	type suppressionSpec struct {
115		ID          *string `json:"id"`
116		ChainID     *string `json:"chainId"`
117		Pool        *string `json:"pool"`
118		Kind        *string `json:"kind"`
119		Channel     *string `json:"channel"`
120		StartHeight *uint64 `json:"startHeight"`
121		EndHeight   *uint64 `json:"endHeight"`
122		Reason      *string `json:"reason"`
123	}
124	
125	func nonEmpty(field string, v *string) (string, error) {
126		if v == nil {
127			return "", fmt.Errorf("%s is required (non-empty string)", field)
128		}
129		if strings.TrimSpace(*v) == "" {
130			return "", fmt.Errorf("%s must be a non-empty string", field)
131		}
132		return *v, nil
133	}
134	
135	// ParseSuppression validates one registration document. Only sandwich and
136	// displacement kinds exist, every text field must be non-empty, heights are
137	// unsigned 64-bit integers and the start height must not exceed the end
138	// height.
139	func ParseSuppression(raw []byte) (Suppression, error) {
140		var spec suppressionSpec
141		dec := json.NewDecoder(bytes.NewReader(raw))
142		dec.DisallowUnknownFields()
143		if err := dec.Decode(&spec); err != nil {
144			return Suppression{}, fmt.Errorf("invalid suppression spec: %w", err)
145		}
146		if dec.More() {
147			return Suppression{}, errors.New("invalid suppression spec: unexpected trailing data")
148		}
149		id, err := nonEmpty("id", spec.ID)
150		if err != nil {
151			return Suppression{}, err
152		}
153		chainID, err := nonEmpty("chainId", spec.ChainID)
154		if err != nil {
155			return Suppression{}, err
156		}
157		pool, err := nonEmpty("pool", spec.Pool)
158		if err != nil {
159			return Suppression{}, err
160		}
161		kind, err := nonEmpty("kind", spec.Kind)
162		if err != nil {
163			return Suppression{}, err
164		}
165		if kind != SuppressSandwich && kind != SuppressDisplacement {
166			return Suppression{}, fmt.Errorf("%w: %q (want sandwich or displacement)", ErrUnknownKind, kind)
167		}
168		channel, err := nonEmpty("channel", spec.Channel)
169		if err != nil {
170			return Suppression{}, err
171		}
172		if spec.StartHeight == nil {
173			return Suppression{}, errors.New("startHeight is required (unsigned 64-bit integer)")
174		}
175		if spec.EndHeight == nil {
176			return Suppression{}, errors.New("endHeight is required (unsigned 64-bit integer)")
177		}
178		if *spec.StartHeight > *spec.EndHeight {
179			return Suppression{}, fmt.Errorf("startHeight %d must not exceed endHeight %d", *spec.StartHeight, *spec.EndHeight)
180		}
181		reason, err := nonEmpty("reason", spec.Reason)
182		if err != nil {
183			return Suppression{}, err
184		}
185		return Suppression{
186			ID:          id,
187			ChainID:     chainID,
188			Pool:        pool,
189			Kind:        kind,
190			Channel:     channel,
191			StartHeight: *spec.StartHeight,
192			EndHeight:   *spec.EndHeight,
193			Reason:      reason,
194		}, nil
195	}
196	
197	// ParseHeight parses a non-negative 64-bit integer height. Signs, fractions,
198	// blanks and values above 2^64-1 are rejected.
199	func ParseHeight(text string) (uint64, error) {
200		if text == "" {
201			return 0, errors.New("height must be a non-empty unsigned 64-bit integer")
202		}
203		h, err := strconv.ParseUint(text, 10, 64)
204		if err != nil {
205			return 0, fmt.Errorf("invalid height %q: %w", text, err)
206		}
207		return h, nil
208	}
209	
210	// ValidateSeverity accepts the integer threshold range 1..5 inclusive; the
211	// threshold itself counts as a hit.
212	func ValidateSeverity(severity int) error {
213		if severity < 1 || severity > 5 {
214			return fmt.Errorf("minSeverity must be between 1 and 5, got %d", severity)
215		}
216		return nil
217	}
218	
219	// suppressionEqual reports whether two conditions carry identical content.
220	func suppressionEqual(a, b Suppression) bool {
221		return a == b
222	}
223	
224	// matchSuppressions returns every condition covering the event, sorted by ID
225	// in lexicographic order so overlapping conditions are reported
226	// deterministically.
227	func matchSuppressions(conds []Suppression, chainID, pool, kind, channel string, height uint64) []SuppressionHit {
228		hits := []SuppressionHit{}
229		for _, s := range conds {
230			if s.covers(chainID, pool, kind, channel, height) {
231				hits = append(hits, SuppressionHit{ID: s.ID, Reason: s.Reason})
232			}
233		}
234		sort.Slice(hits, func(i, j int) bool { return hits[i].ID < hits[j].ID })
235		return hits
236	}
237	
238	// victimPool returns the pool of the victim swap inside the finding's raw
239	// evidence. The victim is the swap whose TxHash matches the finding; the
240	// evidence ordering and count vary by conclusion kind, so the pool is read
241	// off the original exchange record rather than inferred from position.
242	func victimPool(f ReportFinding) (string, bool) {
243		for _, s := range f.Evidence {
244			if s.TxHash == f.TxHash {
245				return s.Pool, true
246			}
247		}
248		return "", false
249	}
250	
251	// sortRecords orders processing records by height, block hash, tx hash and
252	// kind ascending. Channel stays out of the ordering key: generation runs for
253	// one channel, history may span several.
254	func sortRecords(records []ProcessingRecord) {
255		sort.Slice(records, func(i, j int) bool {
256			a, b := records[i], records[j]
257			if a.BlockNumber != b.BlockNumber {
258				return a.BlockNumber < b.BlockNumber
259			}
260			if a.BlockHash != b.BlockHash {
261				return a.BlockHash < b.BlockHash
262			}
263			if a.Finding.TxHash != b.Finding.TxHash {
264				return a.Finding.TxHash < b.Finding.TxHash
265			}
266			return a.Finding.Kind < b.Finding.Kind
267		})
268	}
269	
270	// GenerateAlerts turns archived conclusions in the inclusive range
271	// [startHeight, endHeight] on chainID for channel into new processing
272	// records. Detection is not re-run: the archived finding, evidence and rule
273	// version are reused. A finding at least minSeverity is processed; findings
274	// below the threshold leave no record, so lowering the threshold later can
275	// still produce them. Every already-processed identity is skipped, which
276	// makes repeated imports, repeated generation, wider or overlapping ranges,
277	// version switches and restarts idempotent. Channels are independent, and
278	// blocks at the same height with different hashes are handled separately.
279	//
280	// All new records of one call are committed together or not at all. The
281	// returned slice contains only records created by this call (alerts and
282	// suppressions distinguished), sorted by height, block hash, tx hash and
283	// kind; an empty result serializes as [].
284	func GenerateAlerts(dir, chainID, channel string, startHeight, endHeight uint64, minSeverity int) ([]ProcessingRecord, error) {
285		if strings.TrimSpace(chainID) == "" {
286			return nil, errors.New("chainId must be a non-empty string")
287		}
288		if strings.TrimSpace(channel) == "" {
289			return nil, errors.New("channel must be a non-empty name")
290		}
291		if err := ValidateSeverity(minSeverity); err != nil {
292			return nil, err
293		}
294		if startHeight > endHeight {
295			return nil, fmt.Errorf("startHeight %d must not exceed endHeight %d", startHeight, endHeight)
296		}
297		if err := os.MkdirAll(dir, 0o755); err != nil {
298			return nil, err
299		}
300		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
301		if err != nil {
302			return nil, err
303		}
304		defer lock.Close()
305	
306		data, err := readArchive(dir)
307		if err != nil {
308			return nil, err
309		}
310		processed := make(map[alertKey]struct{}, len(data.AlertRecords))
311		for _, r := range data.AlertRecords {
312			processed[r.identity()] = struct{}{}
313		}
314	
315		created := []ProcessingRecord{}
316		for _, rec := range data.Records {
317			if rec.ChainID != chainID {
318				continue
319			}
320			height := uint64(rec.BlockNumber)
321			if height < startHeight || height > endHeight {
322				continue
323			}
324			version := rec.ruleVersion()
325			for _, f := range rec.Findings {
326				if f.Severity < minSeverity {
327					// Below the threshold: no record is written, so the event
328					// stays eligible after a later threshold reduction.
329					continue
330				}
331				key := alertKey{
332					chainID:   rec.ChainID,
333					blockHash: rec.BlockHash,
334					txHash:    f.TxHash,
335					kind:      f.Kind,
336					channel:   channel,
337				}
338				if _, ok := processed[key]; ok {
339					continue
340				}
341				pool, ok := victimPool(f)
342				if !ok {
343					return nil, fmt.Errorf("archive is corrupted: archived finding for block %s/%s tx %s has no victim swap in its evidence",
344						rec.ChainID, rec.BlockHash, f.TxHash)
345				}
346				hits := matchSuppressions(data.Suppressions, rec.ChainID, pool, f.Kind, channel, height)
347				status := AlertStatusAlert
348				if len(hits) > 0 {
349					status = AlertStatusSuppressed
350				}
351				record := ProcessingRecord{
352					ChainID:      rec.ChainID,
353					BlockHash:    rec.BlockHash,
354					BlockNumber:  height,
355					Pool:         pool,
356					Channel:      channel,
357					Finding:      f,
358					Version:      version,
359					MinSeverity:  minSeverity,
360					Status:       status,
361					Suppressions: hits,
362				}
363				created = append(created, record)
364				processed[key] = struct{}{}
365			}
366		}
367		sortRecords(created)
368		if len(created) > 0 {
369			data.AlertRecords = append(data.AlertRecords, created...)
370			if err := writeArchiveAtomic(dir, data); err != nil {
371				return nil, err
372			}
373		}
374		return created, nil
375	}
376	
377	// AlertHistory returns stored processing records on chainID for channel in
378	// the inclusive range [startHeight, endHeight]. It only reads the archive;
379	// suppressions registered afterwards cannot alter the stored content.
380	func AlertHistory(dir, chainID, channel string, startHeight, endHeight uint64) ([]ProcessingRecord, error) {
381		if strings.TrimSpace(chainID) == "" {
382			return nil, errors.New("chainId must be a non-empty string")
383		}
384		if strings.TrimSpace(channel) == "" {
385			return nil, errors.New("channel must be a non-empty name")
386		}
387		if startHeight > endHeight {
388			return nil, fmt.Errorf("startHeight %d must not exceed endHeight %d", startHeight, endHeight)
389		}
390		if _, serr := os.Stat(dir); serr != nil {
391			if errors.Is(serr, os.ErrNotExist) {
392				return []ProcessingRecord{}, nil
393			}
394			return nil, serr
395		}
396		lock, err := lockArchive(dir, syscall.LOCK_SH)
397		if err != nil {
398			return nil, err
399		}
400		defer lock.Close()
401	
402		data, err := readArchive(dir)
403		if err != nil {
404			return nil, err
405		}
406		out := []ProcessingRecord{}
407		for _, r := range data.AlertRecords {
408			if r.ChainID != chainID || r.Channel != channel {
409				continue
410			}
411			if r.BlockNumber < startHeight || r.BlockNumber > endHeight {
412				continue
413			}
414			out = append(out, r)
415		}
416		sortRecords(out)
417		return out, nil
418	}
419	
420	// RegisterSuppression validates raw and stores one suppression condition in
421	// the archive. Re-registering the same ID with identical content succeeds
422	// without adding anything (created is false); the same ID with different
423	// content is rejected. New conditions only affect conclusions that have not
424	// been processed yet: historical alerts are never rewritten as suppressed,
425	// and suppressed records are not re-alerted when a condition's range ends.
426	func RegisterSuppression(dir string, raw []byte) (s Suppression, created bool, err error) {
427		s, err = ParseSuppression(raw)
428		if err != nil {
429			return Suppression{}, false, err
430		}
431		if err := os.MkdirAll(dir, 0o755); err != nil {
432			return Suppression{}, false, err
433		}
434		lock, lerr := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
435		if lerr != nil {
436			return Suppression{}, false, lerr
437		}
438		defer lock.Close()
439	
440		data, err := readArchive(dir)
441		if err != nil {
442			return Suppression{}, false, err
443		}
444		for _, existing := range data.Suppressions {
445			if existing.ID == s.ID {
446				if suppressionEqual(existing, s) {
447					return existing, false, nil
448				}
449				return Suppression{}, false, fmt.Errorf("%w: %s", ErrSuppressionConflict, s.ID)
450			}
451		}
452		data.Suppressions = append(data.Suppressions, s)
453		if err := writeArchiveAtomic(dir, data); err != nil {
454			return Suppression{}, false, err
455		}
456		return s, true, nil
457	}
458	
459	// ListSuppressions returns every suppression condition stored in the
460	// archive, ordered by ID. A read on an absent archive returns an empty list.
461	func ListSuppressions(dir string) ([]Suppression, error) {
462		if _, serr := os.Stat(dir); serr != nil {
463			if errors.Is(serr, os.ErrNotExist) {
464				return []Suppression{}, nil
465			}
466			return nil, serr
467		}
468		lock, err := lockArchive(dir, syscall.LOCK_SH)
469		if err != nil {
470			return nil, err
471		}
472		defer lock.Close()
473	
474		data, err := readArchive(dir)
475		if err != nil {
476			return nil, err
477		}
478		out := append([]Suppression(nil), data.Suppressions...)
479		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
480		if out == nil {
481			out = []Suppression{}
482		}
483		return out, nil
484	}
485

