687		}
688	}
689	
690	func TestGenerateCorruptedFindingEvidenceLeavesDataUntouched(t *testing.T) {
691		dir := t.TempDir()
692		// Archived finding whose evidence lost the victim swap itself: the pool
693		// cannot be derived, generation must fail without writing anything.
694		data := archiveData{Records: []record{{
695			ChainID: "1", BlockHash: "0xa", BlockNumber: 10,
696			Swaps: []Swap{{TxHash: "0xf", Pool: "p1", Trader: "b", In: 1, Out: 1, GasPrice: 90, Index: 0}},
697			Findings: []ReportFinding{{Kind: "sandwich", Severity: 3, TxHash: "0xv",
698				Evidence: []Swap{{TxHash: "0xf", Pool: "p1", Trader: "b", In: 1, Out: 1, GasPrice: 90, Index: 0}}}},
699		}}}
700		if err := writeArchiveAtomic(dir, data); err != nil {
701			t.Fatal(err)
702		}
703		before, err := os.ReadFile(filepath.Join(dir, archiveFileName))
704		if err != nil {
705			t.Fatal(err)
706		}
707		if _, gerr := GenerateAlerts(dir, "1", "ops", 0, 100, 1); gerr == nil ||
708			!strings.Contains(gerr.Error(), "corrupted") {
709			t.Fatalf("got %v, want corrupted-archive error", gerr)
710		}
711		after, err := os.ReadFile(filepath.Join(dir, archiveFileName))
712		if err != nil {
713			t.Fatal(err)
714		}
715		if !reflect.DeepEqual(before, after) {
716			t.Fatal("failed generation modified the archive")
717		}
718	}
719	
720	func TestGenerateConcurrentNoDuplicates(t *testing.T) {
721		dir := t.TempDir()
722		mustReplay(t, dir, twoFindingsInput)
723	
724		const n = 12
725		var wg sync.WaitGroup
726		results := make([][]ProcessingRecord, n)
727		errs := make([]error, n)
728		start := make(chan struct{})
729		for i := 0; i < n; i++ {
730			wg.Add(1)
731			go func(i int) {
732				defer wg.Done()
733				<-start
734				results[i], errs[i] = GenerateAlerts(dir, "1", "ops", 0, 100, 1)
735			}(i)
736		}
737		close(start)
738		wg.Wait()
739	
740		succeeded, busy := 0, 0
741		for _, err := range errs {
742			switch {
743			case err == nil:
744				succeeded++
745			case errors.Is(err, ErrBusy):
746				busy++
747			default:
748				t.Fatalf("unexpected error: %v", err)
749			}
750		}
751		if succeeded != 1 {
752			t.Fatalf("got %d successful generators and %d busy, want exactly 1 success", succeeded, busy)
753		}
754		hist, err := AlertHistory(dir, "1", "ops", 0, 100)
755		if err != nil {
756			t.Fatal(err)
757		}
758		if len(hist) != 2 {
759			t.Fatalf("history holds %d records, want exactly 2 (no duplicates, no loss)", len(hist))
760		}
761		seen := map[alertKey]bool{}
762		for _, r := range hist {
763			k := r.identity()
764			if seen[k] {
765				t.Fatalf("duplicate processing record: %+v", k)
766			}
767			seen[k] = true
768		}
769	}
770	
771	func TestGenerateOnlyReturnsNewRecords(t *testing.T) {
772		dir := t.TempDir()
773		mustReplay(t, dir, twoFindingsInput)
774		// First generation with a suppression in place: one alert, one suppressed.
775		spec := `{"id":"s","chainId":"1","pool":"p1","kind":"sandwich","channel":"ops","startHeight":10,"endHeight":10,"reason":"r"}`
776		if _, _, err := RegisterSuppression(dir, []byte(spec)); err != nil {
777			t.Fatal(err)
778		}
779		got, err := GenerateAlerts(dir, "1", "ops", 0, 100, 1)
780		if err != nil {
781			t.Fatal(err)
782		}
783		statuses := map[string]string{}
784		for _, r := range got {
785			statuses[r.Finding.Kind] = r.Status
786		}
787		if statuses["sandwich"] != AlertStatusSuppressed || statuses["displacement"] != AlertStatusAlert {
788			t.Fatalf("same call must distinguish alert and suppressed: %+v", statuses)
789		}
790	}
