func TestRevokeSuppressionConcurrentConsistent(t *testing.T) {
	dir := t.TempDir()
	mustReplay(t, dir, twoFindingsInput)
	spec := `{"id":"s1","chainId":"1","pool":"p1","kind":"sandwich","channel":"ops","startHeight":0,"endHeight":200,"reason":"r"}`
	if _, _, err := RegisterSuppression(dir, []byte(spec)); err != nil {
		t.Fatal(err)
	}

	const n = 12
	var wg sync.WaitGroup
	genErrs := make([]error, n)
	statuses := make([]string, n)
	start := make(chan struct{})
	// Half the goroutines generate, half revoke; each generation must
	// observe one consistent condition set (suppressed pre-revoke or alert
	// post-revoke), never a half state.
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			<-start
			if i%2 == 0 {
				recs, err := GenerateAlerts(dir, "1", "ops", 0, 100, 1)
				genErrs[i] = err
				if err == nil {
					for _, r := range recs {
						if r.Finding.TxHash == "0xv" {
							statuses[i] = r.Status
						}
					}
				}
			} else {
				_, _, err := RevokeSuppression(dir, "s1")
				genErrs[i] = err
			}
		}(i)
	}
	close(start)
	wg.Wait()

	var sawBusy int
	for i, err := range genErrs {
		switch {
		case err == nil:
		case errors.Is(err, ErrBusy):
			sawBusy++
		default:
			t.Fatalf("goroutine %d unexpected error: %v", i, err)
		}
	}
	// The sandwich is processed exactly once by one generation; its status
	// must be one coherent outcome.
	hist, err := AlertHistory(dir, "1", "ops", 0, 100)
	if err != nil {
		t.Fatal(err)
	}
	var final string
	count := 0
	for _, r := range hist {
		if r.Finding.TxHash == "0xv" {
			count++
			final = r.Status
			if len(r.Suppressions) > 1 {
				t.Fatalf("inconsistent hit set: %+v", r.Suppressions)
			}
		}
	}
	if count != 1 {
		t.Fatalf("sandwich processed %d times, want exactly 1 (busy=%d)", count, sawBusy)
	}
	if final != AlertStatusAlert && final != AlertStatusSuppressed {
		t.Fatalf("final status %q is neither coherent pre/post-revocation state", final)
	}
}

